import {readdir, readFile} from 'node:fs/promises';
import {createRequire} from 'node:module';
import {dirname, extname, relative, resolve} from 'node:path';

// Resolve from the docs package itself; bundled pages move away from their sources.
const require = createRequire(resolve(process.cwd(), 'package.json'));

export const logosDist = dirname(require.resolve('@earendil-works/elanor-logos/manifest.json'));
export const fontsDist = dirname(require.resolve('@earendil-works/elanor-fonts/earendil.css'));
/** The company brand guidelines as data, generated by the logos build for the Earendil press kit. */
export const companyGuidelines = resolve(logosDist, 'guidelines/earendil.json');
export const iconsDist = dirname(
  require.resolve('@earendil-works/elanor-icons-boiled/metadata.json'),
);
/**
 * The React icons barrel. The package only has `import` conditions, which require.resolve does not match,
 * so it is read through the docs package's own dependency link.
 */
export const iconsReactBarrel = resolve(
  process.cwd(),
  'node_modules/@earendil-works/elanor-icons-boiled-react/dist/index.js',
);

export interface LogoAsset {
  id: string;
  kind: 'logo' | 'logo-wordmark-horizontal' | 'logo-wordmark-vertical';
  treatment: 'on-light' | 'on-dark' | 'monochrome-on-light' | 'monochrome-on-dark';
  scheme: 'light' | 'dark';
  monochrome: boolean;
  width: number;
  height: number;
  files: {svg: string; png?: string; pdf?: Record<string, string>; [key: string]: unknown};
}

export interface LogoBrand {
  id: string;
  name: string;
  backgrounds: Record<'light' | 'dark', string>;
  assets: LogoAsset[];
  favicons?: Record<string, string>;
  avatars?: Array<{treatment: string; size: number; path: string}>;
}

export interface LogoManifest {
  gridUnit: number;
  clearSpace: number;
  brands: LogoBrand[];
  pressKits?: Record<string, string>;
}

/** Every file type the logo build writes. Browsers only render SVG images served with their type. */
const logoContentTypes: Record<string, string> = {
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.pdf': 'application/pdf',
  '.zip': 'application/zip',
  '.json': 'application/json',
  '.webmanifest': 'application/manifest+json',
  '.md': 'text/markdown; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
};

export function logoContentType(path: string): string {
  const contentType = logoContentTypes[extname(path)];
  if (!contentType)
    throw new Error(`No content type for logo file ${path}; add its extension to logoContentTypes`);
  return contentType;
}

/** The site's favicons: the Elanor brand's, from the logo package's manifest, by manifest key. */
export async function siteFavicons(): Promise<Record<string, string>> {
  const manifest = JSON.parse(
    await readFile(resolve(logosDist, 'manifest.json'), 'utf8'),
  ) as LogoManifest;
  const favicons = manifest.brands.find(({id}) => id === 'elanor')?.favicons;
  if (!favicons)
    throw new Error('The logo build has no Elanor favicons; rebuild @earendil-works/elanor-logos');
  return favicons;
}

export interface GuidelinesImage {
  /** Relative to the logo package's dist/. */
  path: string;
  alt: string;
  width: number;
}

export interface GuidelinesData {
  title: string;
  intro: {markdown: string; html: string};
  sections: Array<{
    id: string;
    title: string;
    markdown: string;
    html: string;
    images: GuidelinesImage[];
  }>;
}

export interface IconEntry {
  tags: string[];
}

/** Every file below a directory, as paths relative to it. */
export async function listFiles(directory: string): Promise<string[]> {
  const entries = await readdir(directory, {recursive: true, withFileTypes: true});
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => relative(directory, resolve(entry.parentPath, entry.name)))
    .sort();
}
